function remplirMatrice(grille, x, y, nouvelleValeur) {
  const ancienneValeur = grille[y][x];
  if (ancienneValeur === nouvelleValeur) return grille;
  const lignes = grille.length;
  const colonnes = grille[0].length;
  function remplir(l, c) {
    if (l < 0 || l >= lignes || c < 0 || c >= colonnes) return;
    if (grille[l][c] !== ancienneValeur) return;
    grille[l][c] = nouvelleValeur;
    remplir(l + 1, c);
    remplir(l - 1, c);
    remplir(l, c + 1);
    remplir(l, c - 1);
  }
  remplir(y, x);
  return grille;
}
