class Trie {
  constructor() {
    this.root = { children: {}, isEnd: false };
  }
  inserer(mot) {
    let node = this.root;
    for (const char of mot) {
      if (!node.children[char]) node.children[char] = { children: {}, isEnd: false };
      node = node.children[char];
    }
    node.isEnd = true;
  }
  chercher(mot) {
    const node = this._traverse(mot);
    return node !== null && node.isEnd;
  }
  commencePar(prefixe) {
    return this._traverse(prefixe) !== null;
  }
  suggestions(prefixe) {
    const node = this._traverse(prefixe);
    if (!node) return [];
    const results = [];
    const dfs = (n, path) => {
      if (n.isEnd) results.push(prefixe + path);
      for (const char of Object.keys(n.children).sort()) {
        dfs(n.children[char], path + char);
      }
    };
    dfs(node, '');
    return results;
  }
  _traverse(str) {
    let node = this.root;
    for (const char of str) {
      if (!node.children[char]) return null;
      node = node.children[char];
    }
    return node;
  }
}
