function dijkstra(graphe, depart) {
  const dist = {};
  const visited = new Set();
  const allNodes = new Set();
  for (const u in graphe) {
    allNodes.add(u);
    for (const v in graphe[u]) {
      allNodes.add(v);
    }
  }
  for (const node of allNodes) dist[node] = Infinity;
  dist[depart] = 0;
  while (true) {
    let u = null;
    let minDist = Infinity;
    for (const node of allNodes) {
      if (!visited.has(node) && dist[node] < minDist) {
        minDist = dist[node];
        u = node;
      }
    }
    if (u === null) break;
    visited.add(u);
    const neighbors = graphe[u] || {};
    for (const v in neighbors) {
      const alt = dist[u] + neighbors[v];
      if (alt < dist[v]) {
        dist[v] = alt;
      }
    }
  }
  return dist;
}
