function remplirMatrice(grille, x, y, nouvelleValeur) {
    const ancienneValeur = grille[y][x];
    if (ancienneValeur === nouvelleValeur) return grille;
    const rows = grille.length;
    const cols = grille[0].length;
    function flood(fx, fy) {
        if (fx < 0 || fx >= cols || fy < 0 || fy >= rows) return;
        if (grille[fy][fx] !== ancienneValeur) return;
        grille[fy][fx] = nouvelleValeur;
        flood(fx + 1, fy);
        flood(fx - 1, fy);
        flood(fx, fy + 1);
        flood(fx, fy - 1);
    }
    flood(x, y);
    return grille;
}

