function optimisation_extreme(arr, target) {
    const seen = new Set();
    for (let i = 0; i < arr.length; i++) {
        const complement = target - arr[i];
        if (seen.has(complement)) {
            return true;
        }
        seen.add(arr[i]);
    }
    return false;
}

function fusionnerIntervalles(tab) {
    if (tab.length <= 1) return tab.slice();
    const sorted = tab.slice().sort((a, b) => a[0] - b[0]);
    const result = [sorted[0].slice()];
    for (let i = 1; i < sorted.length; i++) {
        const last = result[result.length - 1];
        if (sorted[i][0] <= last[1]) {
            last[1] = Math.max(last[1], sorted[i][1]);
        } else {
            result.push(sorted[i].slice());
        }
    }
    return result;
}

function prefixeCommun(tab) {
    if (!tab || tab.length === 0) return '';
    let prefix = tab[0];
    for (let i = 1; i < tab.length; i++) {
        while (tab[i].indexOf(prefix) !== 0) {
            prefix = prefix.slice(0, -1);
            if (prefix === '') return '';
        }
    }
    return prefix;
}

function nombreDeBits1(n) {
