}

function medianeDeuxTries(a, b) {
    if (a.length > b.length) {
        return medianeDeuxTries(b, a);
    }
    const m = a.length;
    const n = b.length;
    let lo = 0;
    let hi = m;
    while (lo <= hi) {
        const partitionA = Math.floor((lo + hi) / 2);
        const partitionB = Math.floor((m + n + 1) / 2) - partitionA;
        const maxLeftA = partitionA === 0 ? -Infinity : a[partitionA - 1];
        const minRightA = partitionA === m ? Infinity : a[partitionA];
        const maxLeftB = partitionB === 0 ? -Infinity : b[partitionB - 1];
        const minRightB = partitionB === n ? Infinity : b[partitionB];
        if (maxLeftA <= minRightB && maxLeftB <= minRightA) {
            if ((m + n) % 2 === 0) {
                return (Math.max(maxLeftA, maxLeftB) + Math.min(minRightA, minRightB)) / 2;
            } else {
                return Math.max(maxLeftA, maxLeftB);
            }
        } else if (maxLeftA > minRightB) {
            hi = partitionA - 1;
        } else {
            lo = partitionA + 1;
        }
    }
    return 0;
}

function plusLongueSousSuiteCroissante(tab) {
    if (tab.length === 0) return 0;
    const tails = [];
    for (let i = 0; i < tab.length; i++) {
        const num = tab[i];
        let lo = 0;
        let hi = tails.length;
        while (lo < hi) {
            const mid = Math.floor((lo + hi) / 2);
            if (tails[mid] < num) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        tails[lo] = num;
    }
    return tails.length;
}
